const mammoth = require('mammoth');
const PDFDocument = require('pdfkit');
const fs = require('fs');
const path = require('path');

const inputPath = path.resolve('/workspace/testbed/docs/customer_report.docx');
const outputPath = path.resolve('/workspace/testbed/docs/customer_report.pdf');

(async () => {
  try {
    // Extract raw text with structure hints from mammoth
    const result = await mammoth.extractRawText({ path: inputPath });
    const text = result.value;

    const doc = new PDFDocument({
      size: 'A4',
      margins: { top: 50, bottom: 50, left: 60, right: 60 },
    });

    const stream = fs.createWriteStream(outputPath);
    doc.pipe(stream);

    const lines = text.split('\n');
    let isFirstLine = true;

    for (const line of lines) {
      const trimmed = line.trim();
      if (trimmed === '') {
        doc.moveDown(0.5);
        continue;
      }

      // Heuristic: lines that are short and look like headings (all caps or short phrases)
      if (isFirstLine) {
        doc.fontSize(18).font('Helvetica-Bold').text(trimmed, { align: 'center' });
        doc.moveDown(1);
        isFirstLine = false;
      } else if (trimmed.length < 60 && trimmed === trimmed.toUpperCase() && /[A-Z]/.test(trimmed)) {
        doc.moveDown(0.5);
        doc.fontSize(14).font('Helvetica-Bold').text(trimmed);
        doc.moveDown(0.3);
      } else if (trimmed.endsWith(':') && trimmed.length < 60) {
        doc.moveDown(0.3);
        doc.fontSize(12).font('Helvetica-Bold').text(trimmed);
        doc.moveDown(0.2);
      } else {
        doc.fontSize(11).font('Helvetica').text(trimmed, { align: 'left', lineGap: 3 });
      }
    }

    doc.end();

    stream.on('finish', () => {
      console.log(`PDF created successfully: ${outputPath}`);
      const stats = fs.statSync(outputPath);
      console.log(`File size: ${stats.size} bytes`);
    });

    stream.on('error', (err) => {
      console.error('Error writing PDF:', err);
    });

    if (result.messages.length > 0) {
      console.log('Conversion messages:', result.messages);
    }
  } catch (err) {
    console.error('Error:', err);
    process.exit(1);
  }
})();

